internal sealed class LatticeLightConeCoordinatesDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original lattice light-cone algebra", H("LatticeLightConeCoordinates"), Blocks(
        Paragraph(Text("The complex bilinear coordinate change preserves the original integral labels, oscillator variables and carrier. It supplies algebraic tools for later quartet calculations; it does not prove a BRST contraction or any no-ghost or string endpoint. Classical lattice-current context is Bakalov--Kac, arXiv math/0402315v1, section 4.1; the source-level coordinate construction and transport proofs are supplied here.")),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-0"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.frameEquiv"), H("NullFrame.frameEquiv"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A frame consists only of two actual vectors with g(ePlus,ePlus)=g(eMinus,eMinus)=0 and g(ePlus,eMinus)=1. The explicitly proved linear equivalence sends v in the original E D to (g(eMinus,v),g(ePlus,v),projK(v)), with inverse a ePlus + b eMinus + k. K is the actual simultaneous kernel of the two Gram pairings."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-1"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.polynomialEquiv"), H("polynomialEquiv"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every genuine finite basis b of the original complex space E D, frequencywise linear variable substitution and its explicit inverse give an algebra equivalence from the original Oscillator D. Both inverse laws are proved on variables; no transport certificate is a premise."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-2"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.vector_substitution"), H("NullFrame.vector_substitution"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every D, null frame F, t, actual basis B of F.K, original vector v and frequency index r, the image of lin(r,v) is g(eMinus,v) X(plus,r)+g(ePlus,v) X(minus,r)+the B-coordinates of projK(v) in the transverse variables."))), DescribeRole.Theorem),
        Paragraph(Text("For every actual frame and transverse basis, the inverse sends the plus and minus variables to lin(r,ePlus) and lin(r,eMinus), and the jth transverse variable to lin(r,B(j)) in the original polynomial algebra.")),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-4"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.creation_plus"), H("NullFrame.creation_plus"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original integral charge p, r and polynomial P, a(ePlus,-r-1) becomes multiplication by X(plus,r)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-5"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.creation_minus"), H("NullFrame.creation_minus"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original integral charge p, r and polynomial P, a(eMinus,-r-1) becomes multiplication by X(minus,r)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-6"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.annihilation_minus"), H("NullFrame.annihilation_minus"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original integral charge p, r and polynomial P, a(eMinus,r+1) becomes (r+1) times partial differentiation in X(plus,r). The Gram pairing swaps the longitudinal derivative directions."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-7"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.annihilation_plus"), H("NullFrame.annihilation_plus"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original integral charge p, r and polynomial P, a(ePlus,r+1) becomes (r+1) times partial differentiation in X(minus,r)."))), DescribeRole.Theorem),
        Paragraph(Text("For every original integral charge p and P, the ePlus zero mode acts by pPlus(p)=g(ePlus,chargeVector(p)), with no nonzero-charge assumption needed for this identity.")),
        Paragraph(Text("For every original integral charge p and P, the eMinus zero mode acts by pMinus(p)=g(eMinus,chargeVector(p)).")),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-10"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.creation_K"), H("NullFrame.creation_K"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every k in the actual K, original charge p, r and P, the negative current is multiplication by the sum of B-coordinates of k times the original-frequency transverse variables."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-11"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.annihilation_K"), H("NullFrame.annihilation_K"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every k in the actual K, original charge p, r and P, the positive current is (r+1) times the sum of g(k,B(j)) times transverse partial derivatives. The transverse basis need not be orthogonal or integral."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-12"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.original_carrier_all_charges"), H("NullFrame.original_carrier_all_charges"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original complex direction u, integer m and original finite-charge state v, allChargeEquiv intertwines the actual original current a(u,m) with the explicitly constructed chargewise coordinateMode. The support index remains exactly Charge D."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("latticelightconecoordinates-13"), DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeLightConeCoordinates.frequency_grading"), H("NullFrame.frequency_grading"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every original D, F, actual basis B of F.K, P and natural n, the transformed polynomial is homogeneous of frequency n if and only if P is homogeneous for the original oscillatorWeight D. Each original variable (i,r) retains weight r+1 in both substitutions."))), DescribeRole.Theorem))));
